var t=`0669-fufu-and-light-soup`;var i=`world-0669`;var a=`GH`;var o=`western-africa`;var s=4;var r=95;var g={en:`Fufu and Light Soup`,ua:`Фуфу з легким супом`};var d={en:`Fufu and Light Soup is a Ghana classic prepared with yam, plantain, yellow onion, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Фуфу з легким супом, страва кухні країни Гана зі складниками: ямс, плантан, жовта цибуля, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Cook the listed ingredients in simmering water for about 27 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 27 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:27,i:[[`yam`,600,`g`],[`plantain`,450,`g`],[`water`,1100,`ml`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 12 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 12 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:12,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,160,`g`],[`tomato`,310,`g`],[`red-palm-oil`,45,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 42 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 42 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:42,i:[[`goat-meat`,520,`g`],[`water`,750,`ml`],[`ginger-root`,25,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,15,`g`]]}];var l={slug:t,id:i,country:`GH`,region:o,servings:4,minutes:95,title:g,text:d,steps:u};export{a as country,l as default,i as id,r as minutes,o as region,s as servings,t as slug,u as steps,d as text,g as title};